import {
  type ComputedRef,
  computed,
  onBeforeUnmount,
  onMounted,
  type Ref,
  ref,
  shallowRef,
  watch,
} from "vue";
import {
  type DashboardColumn,
  type DashboardFilterValue,
  type DashboardStorage,
  type DashboardTableInfo,
  type DashboardView,
  type DashboardViewerFilters,
  dashboardColumn,
  loadDashboardViews,
  setDashboardViewerFilter,
} from "./dashboard-model";
import {
  canonicalDashboardJson,
  type Dashboard,
  type DashboardBlocks,
  normalizeDashboard,
} from "./dashboard-schema";
import {
  createDashboardSourceLoader,
  type DashboardSourceLoader,
  type DashboardSourceState,
  type DashboardSourceSummary,
  type DashboardSources,
} from "./dashboard-sources";
import type { DashboardTableSource } from "./dashboard-types";
import {
  readDashboardUrlFilters,
  writeDashboardUrlFilters,
} from "./dashboard-url";

export type DashboardLoadState =
  | { status: "loading" | "ready" | "empty" }
  | { status: "error"; message: string };

export const errorText = (error: unknown) =>
  error instanceof Error ? error.message : String(error);

/** What the dashboard knows of a loaded source: its name, columns and formats. */
export const tableInfo = (
  tableId: string,
  source: DashboardTableSource
): DashboardTableInfo => ({
  name: source.name ?? source.config.translations?.keys?.title ?? tableId,
  coloredTags: source.config.table?.coloredTags,
  defaultDisplayMode: source.config.table?.defaultDisplayMode,
  columns: source.config.columns.definitions.map((column) =>
    dashboardColumn(column as DashboardColumn)
  ),
});

/** A loaded source's summary, for the catalogue and reference checks. */
export const summarizeSource = (
  id: string,
  source: DashboardTableSource
): DashboardSourceSummary => ({
  id,
  name: tableInfo(id, source).name,
  columns: source.config.columns.definitions.map((column) => ({
    id: column.id,
    ...(typeof column.header === "string" ? { header: column.header } : {}),
    ...(column.type ? { type: String(column.type) } : {}),
  })),
  displayModes: [...(source.config.table?.displayModes ?? ["table"])],
  views: (source.views ?? []).map((view) => ({
    id: view.id,
    name: view.name,
    ...(view.config.displayMode
      ? { displayMode: String(view.config.displayMode) }
      : {}),
  })),
});

/**
 * The document: `dashboard` when the host gives one (shown again when it
 * changes; equal documents keep the edits in progress), else loaded from
 * storage (`dashboardId`, else the first listed). Documents are read with the
 * host's blocks (misplaced blocks move).
 */
export function useDashboardDocument(options: {
  input: () => unknown;
  storage: () => DashboardStorage | undefined;
  dashboardId: () => string | undefined;
  blocks: () => DashboardBlocks | undefined;
}) {
  const dashboard = shallowRef<Dashboard>();
  const state = ref<DashboardLoadState>({ status: "loading" });
  let shown = "";
  let loading = 0;
  /** The host's document, shown when it changed. */
  const show = (input: unknown) => {
    try {
      const next = normalizeDashboard(input, { blocks: options.blocks() });
      const json = canonicalDashboardJson(next);
      if (json !== shown) {
        shown = json;
        dashboard.value = next;
      }
      state.value = { status: "ready" };
    } catch (error) {
      state.value = { status: "error", message: errorText(error) };
    }
  };
  /** The stored document (`dashboardId`, else the first listed). */
  const readStored = async (storage: DashboardStorage, attempt: number) => {
    state.value = { status: "loading" };
    try {
      const id = options.dashboardId() ?? (await storage.list())[0]?.id;
      const loaded = id
        ? normalizeDashboard(await storage.load(id), {
            blocks: options.blocks(),
          })
        : undefined;
      if (attempt === loading) {
        dashboard.value = loaded;
        state.value = { status: loaded ? "ready" : "empty" };
      }
    } catch (error) {
      if (attempt === loading) {
        state.value = { status: "error", message: errorText(error) };
      }
    }
  };
  const load = async () => {
    const attempt = ++loading;
    const input = options.input();
    const storage = options.storage();
    if (input !== undefined) {
      show(input);
    } else if (storage) {
      await readStored(storage, attempt);
    } else {
      state.value = { status: "empty" };
    }
  };
  watch(
    () => [options.input(), options.storage(), options.dashboardId()],
    load,
    { immediate: true }
  );
  return { dashboard, state };
}

/**
 * The screen's sources: `tables` (ready at once, winning over the catalogue)
 * and the lazy `sources`, loaded only for the ids asked. `stateOf` follows
 * each source's state reactively.
 */
export function useDashboardSources(options: {
  ids: () => readonly string[];
  sources: () => DashboardSources<DashboardTableSource> | undefined;
  tables: () => Record<string, DashboardTableSource> | undefined;
}): {
  loader: Ref<DashboardSourceLoader<DashboardTableSource>>;
  stateOf: (
    id: string
  ) => DashboardSourceState<DashboardTableSource> | undefined;
} {
  const create = () =>
    createDashboardSourceLoader<DashboardTableSource>({
      sources: options.sources(),
      tables: options.tables(),
      summarize: summarizeSource,
    });
  const loader = shallowRef(create());
  // The loader's states, copied on each change so templates follow them.
  const states = shallowRef(
    new Map<string, DashboardSourceState<DashboardTableSource> | undefined>()
  );
  const follow = (current: DashboardSourceLoader<DashboardTableSource>) =>
    current.subscribe((id) => {
      states.value = new Map(states.value).set(id, current.state(id));
    });
  let unsubscribe = follow(loader.value);
  watch([options.sources, options.tables], () => {
    unsubscribe();
    loader.value = create();
    states.value = new Map();
    unsubscribe = follow(loader.value);
  });
  onBeforeUnmount(() => unsubscribe());
  watch(
    () => [loader.value, options.ids().join("\n")] as const,
    ([current, key]) => {
      for (const id of key ? key.split("\n") : []) {
        current.load(id).catch(() => undefined);
      }
    },
    { immediate: true }
  );
  return { loader, stateOf: (id) => states.value.get(id) };
}

/**
 * Saved views of the sources asked, once each is ready (static views, then
 * `views.list`); a source loaded anew (new tables or catalogue) asks again.
 */
export function useSourceViews(
  stateOf: (
    id: string
  ) => DashboardSourceState<DashboardTableSource> | undefined,
  ids: () => readonly string[]
): Ref<Record<string, DashboardView[] | undefined>> {
  const views = ref<Record<string, DashboardView[] | undefined>>({});
  const asked = new Map<string, DashboardTableSource>();
  watch(
    () => ids().filter((id) => stateOf(id)?.status === "ready"),
    (ready) => {
      for (const id of ready) {
        const state = stateOf(id);
        if (state?.status !== "ready" || asked.get(id) === state.source) {
          continue;
        }
        const source = state.source;
        asked.set(id, source);
        loadDashboardViews(source, id)
          .catch(() => loadDashboardViews({ views: source.views }, id))
          .then((loaded) => {
            if (asked.get(id) === source) {
              views.value = { ...views.value, [id]: loaded };
            }
          })
          .catch(() => undefined);
      }
    },
    { immediate: true }
  );
  return views;
}

/**
 * The values a reader picks for the filters: view state, synced to the URL
 * (`<dashboardId>.<filterId>`) unless `syncUrl` is false, never written to
 * the document. `ready` once the URL was read (after mounting, as the server
 * has no URL), so widgets query once, with the reader's values.
 */
export function useViewerFilters(
  dashboard: () => Pick<Dashboard, "id" | "filters"> | undefined,
  syncUrl: () => boolean
) {
  const values = shallowRef<DashboardViewerFilters>({});
  const mounted = ref(false);
  const ready = computed(() => mounted.value || !syncUrl());
  const shape = computed(() => {
    const doc = dashboard();
    return doc
      ? JSON.stringify([
          doc.id,
          doc.filters.map((filter) => [filter.id, filter.type]),
        ])
      : "";
  });
  const readUrl = () => {
    const doc = dashboard();
    if (doc && syncUrl()) {
      values.value = readDashboardUrlFilters(doc);
    }
  };
  watch([shape, syncUrl], () => {
    if (mounted.value) {
      readUrl();
    }
  });
  onMounted(() => {
    readUrl();
    mounted.value = true;
    window.addEventListener("popstate", readUrl);
  });
  onBeforeUnmount(() => window.removeEventListener("popstate", readUrl));
  const write = (next: DashboardViewerFilters) => {
    values.value = next;
    const doc = dashboard();
    if (doc && syncUrl()) {
      writeDashboardUrlFilters(doc, next);
    }
  };
  const set = (filterId: string, value: DashboardFilterValue | undefined) => {
    const doc = dashboard();
    if (doc) {
      write(setDashboardViewerFilter(doc, values.value, filterId, value));
    }
  };
  return { values, set, clear: () => write({}), ready };
}

interface SourceRevision {
  /** "Refresh all" and refreshes of this source: every widget reloads. */
  refresh: number;
  /** Changes made in a page table: the source's other widgets reload. */
  mutation: number;
}

const MUTATION_DELAY = 150;

/**
 * When widgets load again: "Refresh all", a block's `refresh(tableId)`, and
 * changes made in a page table (grouped: an import or a bulk edit reloads
 * once).
 */
export function useDashboardRevisions() {
  const revision = ref(0);
  const sources = shallowRef<Record<string, SourceRevision>>({});
  const pending = new Set<string>();
  let timer: ReturnType<typeof setTimeout> | undefined;
  onBeforeUnmount(() => clearTimeout(timer));
  const bump = (ids: Iterable<string>, key: keyof SourceRevision) => {
    const next = { ...sources.value };
    for (const id of ids) {
      const known = next[id] ?? { refresh: 0, mutation: 0 };
      next[id] = { ...known, [key]: known[key] + 1 };
    }
    sources.value = next;
  };
  const refresh = (tableId?: string) => {
    if (tableId) {
      bump([tableId], "refresh");
    } else {
      revision.value += 1;
    }
  };
  const mutated = (tableId: string) => {
    pending.add(tableId);
    clearTimeout(timer);
    timer = setTimeout(() => {
      const ids = [...pending];
      pending.clear();
      bump(ids, "mutation");
    }, MUTATION_DELAY);
  };
  const blockRevision: ComputedRef<number> = computed(() => {
    let total = revision.value;
    for (const entry of Object.values(sources.value)) {
      total += entry.refresh + entry.mutation;
    }
    return total;
  });
  return {
    revision,
    refresh,
    mutated,
    /** Numbers and views: "Refresh all", refreshes and changes of their source. */
    widgetRevision: (tableId?: string) => {
      const entry = tableId ? sources.value[tableId] : undefined;
      return revision.value + (entry ? entry.refresh + entry.mutation : 0);
    },
    /** Page tables: "Refresh all" and refreshes of their source (their own changes reload them already). */
    pageRevision: (tableId: string) =>
      revision.value + (sources.value[tableId]?.refresh ?? 0),
    /** Blocks: any of them. */
    blockRevision,
  };
}

/**
 * The screen editor's rules, shared by the React and Vue editions (synced to
 * Vue by `scripts/sync-table-contracts.mjs`): sections (add, rename, move,
 * remove), moving widgets between sections, what the widget dialog offers
 * (kinds, blocks, the source catalogue), the view editor (what changed and
 * what to apply), inline copies of saved views, block props typed as JSON and
 * where a validation issue points. Pure and server-safe (no React, Vue or
 * CSS).
 */
import { canonicalViewConfig, type ViewConfig } from "../view-config";
import {
  type DashboardTranslate,
  type DashboardView,
  dashboardLabel,
  dashboardTextInput,
  dashboardUnavailableText,
  editDashboardText,
} from "./dashboard-model";
import {
  checkDashboardBlockProps,
  DASHBOARD_LIMITS,
  type Dashboard,
  type DashboardBlocks,
  type DashboardInlineView,
  type DashboardIssue,
  type DashboardJsonObject,
  type DashboardLimits,
  type DashboardSection,
  type DashboardSectionType,
  type DashboardWidget,
  dashboardAcceptedSections,
  dashboardText,
  dashboardWidgetSection,
  moveWidgetToSection,
  removeDashboardWidget,
} from "./dashboard-schema";
import type { DashboardSourceSummary } from "./dashboard-sources";

/** What the screen editor opens: one dialog at a time. */
export type DashboardEditorRequest =
  | { kind: "addWidget"; sectionId?: string }
  | { kind: "editWidget"; widgetId: string }
  | { kind: "editView"; widgetId: string }
  | { kind: "removeSection"; sectionId: string }
  | { kind: "addFilter" };

/** What the widget dialog does: add a widget (to a section, else the first that takes it) or edit one. */
export type DashboardWidgetDialogTarget =
  | { mode: "add"; sectionId?: string; sectionType?: DashboardSectionType }
  | { mode: "edit"; widget: DashboardWidget };

// Sections ---------------------------------------------------------------------------

/** Moves a section makes in the page: one place up or down. */
export type DashboardSectionMove = "up" | "down";

/** The widgets a section places, in its order (a grid's layout, a flow's list). */
export const dashboardSectionWidgetIds = (
  section: DashboardSection
): string[] =>
  section.type === "grid"
    ? section.layout.map((item) => item.widgetId)
    : [...section.widgetIds];

/** Whether another section can be added (`DASHBOARD_LIMITS.sections`, 12). */
export const canAddDashboardSection = (
  dashboard: Pick<Dashboard, "sections">,
  limits: Partial<Pick<DashboardLimits, "sections">> = {}
): boolean =>
  dashboard.sections.length < (limits.sections ?? DASHBOARD_LIMITS.sections);

/** Whether a section can move one place that way. */
export function canMoveDashboardSection(
  dashboard: Pick<Dashboard, "sections">,
  sectionId: string,
  direction: DashboardSectionMove
): boolean {
  const index = dashboard.sections.findIndex(
    (section) => section.id === sectionId
  );
  if (index < 0) {
    return false;
  }
  return direction === "up" ? index > 0 : index < dashboard.sections.length - 1;
}

/** A section moved one place up or down; unchanged when it cannot move. */
export function moveDashboardSection(
  dashboard: Dashboard,
  sectionId: string,
  direction: DashboardSectionMove
): Dashboard {
  if (!canMoveDashboardSection(dashboard, sectionId, direction)) {
    return dashboard;
  }
  const sections = [...dashboard.sections];
  const index = sections.findIndex((section) => section.id === sectionId);
  const other = index + (direction === "up" ? -1 : 1);
  const [moved] = sections.splice(index, 1);
  if (moved) {
    sections.splice(other, 0, moved);
  }
  return { ...dashboard, sections };
}

/**
 * Removes a section and the widgets it holds, with their mentions in filter
 * targets. Editors ask first when the section is not empty.
 */
export function removeDashboardSection(
  dashboard: Dashboard,
  sectionId: string
): Dashboard {
  const section = dashboard.sections.find((item) => item.id === sectionId);
  if (!section) {
    return dashboard;
  }
  let next = dashboard;
  for (const widgetId of dashboardSectionWidgetIds(section)) {
    next = removeDashboardWidget(next, widgetId);
  }
  return {
    ...next,
    sections: next.sections.filter((item) => item.id !== sectionId),
  };
}

/**
 * A section renamed in `locale`: a plain title stays plain, a localized one
 * keeps its other languages; an empty title removes it (the section then
 * shows no heading).
 */
export function renameDashboardSection(
  dashboard: Dashboard,
  sectionId: string,
  title: string,
  locale: string
): Dashboard {
  return {
    ...dashboard,
    sections: dashboard.sections.map((section) => {
      if (section.id !== sectionId) {
        return section;
      }
      const { title: previous, ...rest } = section;
      const next = editDashboardText(previous, locale, title);
      return (next ? { ...rest, title: next } : rest) as DashboardSection;
    }),
  };
}

/** What a section's title input shows in `locale` (no other language's version). */
export const dashboardSectionTitleInput = (
  section: Pick<DashboardSection, "title">,
  locale: string
): string => dashboardTextInput(section.title, locale);

/** A section's name in menus: its title, else "Section 2". */
export function dashboardSectionName(
  dashboard: Pick<Dashboard, "sections">,
  sectionId: string,
  locale: string,
  translate?: DashboardTranslate
): string {
  const index = dashboard.sections.findIndex(
    (section) => section.id === sectionId
  );
  const title = dashboardText(dashboard.sections[index]?.title, locale);
  return (
    title ||
    dashboardLabel("sectionNumber", locale, translate, { number: index + 1 })
  );
}

// Moving widgets between sections -----------------------------------------------------

/** A section a widget can move to. */
export interface DashboardSectionChoice {
  id: string;
  type: DashboardSectionType;
  /** Its title, else "Section 2". */
  name: string;
}

/** The other sections that take a widget (a full-page table only flows, a block where its host puts it), in order. */
export function dashboardWidgetMoveTargets(
  dashboard: Dashboard,
  widgetId: string,
  options: {
    blocks?: DashboardBlocks;
    locale: string;
    translate?: DashboardTranslate;
  }
): DashboardSectionChoice[] {
  const widget = dashboard.widgets.find((item) => item.id === widgetId);
  if (!widget) {
    return [];
  }
  const from = dashboardWidgetSection(dashboard, widgetId);
  const accepted = dashboardAcceptedSections(widget, options.blocks);
  return dashboard.sections
    .filter(
      (section) => section.id !== from?.id && accepted.includes(section.type)
    )
    .map((section) => ({
      id: section.id,
      type: section.type,
      name: dashboardSectionName(
        dashboard,
        section.id,
        options.locale,
        options.translate
      ),
    }));
}

/**
 * Moves a widget to another section: at the first free spot of a grid (a
 * card keeps its size; one from a flow takes `size`, its type's by default),
 * at the end of a flow. Unchanged when the section cannot hold it.
 */
export function moveDashboardWidgetToSection(
  dashboard: Dashboard,
  widgetId: string,
  sectionId: string,
  options: { blocks?: DashboardBlocks; size?: { w: number; h: number } } = {}
): Dashboard {
  const from = dashboardWidgetSection(dashboard, widgetId);
  return moveWidgetToSection(dashboard, widgetId, sectionId, {
    ...(options.blocks ? { blocks: options.blocks } : {}),
    ...(from?.type !== "grid" && options.size ? { size: options.size } : {}),
  });
}

/**
 * A widget changed in the widget dialog: its id and place are kept. A widget
 * whose section can no longer hold it (another block) moves to the first
 * section that can.
 */
export function updateDashboardWidget(
  dashboard: Dashboard,
  widgetId: string,
  widget: Omit<DashboardWidget, "id">,
  blocks?: DashboardBlocks
): Dashboard {
  if (!dashboard.widgets.some((item) => item.id === widgetId)) {
    return dashboard;
  }
  const next: Dashboard = {
    ...dashboard,
    widgets: dashboard.widgets.map((item) =>
      item.id === widgetId ? { ...widget, id: widgetId } : item
    ),
  };
  const section = dashboardWidgetSection(next, widgetId);
  const accepted = dashboardAcceptedSections(widget, blocks);
  if (!section || accepted.includes(section.type)) {
    return next;
  }
  const target = next.sections.find((item) => accepted.includes(item.type));
  return target
    ? moveWidgetToSection(next, widgetId, target.id, blocks ? { blocks } : {})
    : next;
}

// What the widget dialog offers ---------------------------------------------------------

/** What a widget can be, as the widget dialog lists it. */
export type DashboardWidgetKind = DashboardWidget["type"];

export interface DashboardWidgetChoice {
  kind: DashboardWidgetKind;
  /** Blocks: the host's key. */
  block?: string;
  label: string;
  description?: string;
  /** The heading it is listed under: empty for the built-in kinds, a block's `group` (else "Blocks"). */
  group: string;
}

const KIND_LABELS = {
  kpi: ["kindKpi", "kindKpiHint"],
  view: ["kindView", "kindViewHint"],
  table: ["kindTable", "kindTableHint"],
  note: ["kindNote", "kindNoteHint"],
} as const;

/**
 * What the widget dialog offers for a section (for any section without one):
 * a number, a view, a full-page table (flows only), a note, then the host's
 * blocks that section takes (their `placement`), by group in the order the
 * host lists them.
 */
export function dashboardWidgetChoices(options: {
  section?: DashboardSectionType;
  blocks?: DashboardBlocks;
  locale: string;
  translate?: DashboardTranslate;
}): DashboardWidgetChoice[] {
  const { blocks, locale, section, translate } = options;
  const label = (key: Parameters<typeof dashboardLabel>[0]) =>
    dashboardLabel(key, locale, translate);
  const takes = (type: DashboardWidgetKind, block?: string) =>
    !section ||
    dashboardAcceptedSections({ type, block }, blocks).includes(section);
  const builtIn = (Object.keys(KIND_LABELS) as (keyof typeof KIND_LABELS)[])
    .filter((kind) => takes(kind))
    .map((kind) => ({
      kind,
      label: label(KIND_LABELS[kind][0]),
      description: label(KIND_LABELS[kind][1]),
      group: "",
    }));
  const hosted = Object.entries(blocks ?? {})
    .filter(([key]) => takes("block", key))
    .map(([key, block]): DashboardWidgetChoice => {
      const description = dashboardText(block.description, locale);
      return {
        kind: "block",
        block: key,
        label: dashboardText(block.label, locale) || key,
        ...(description ? { description } : {}),
        group: dashboardText(block.group, locale) || label("blocks"),
      };
    });
  const groups = [...new Set(hosted.map((choice) => choice.group))];
  return [
    ...builtIn,
    ...groups.flatMap((group) =>
      hosted.filter((choice) => choice.group === group)
    ),
  ];
}

/** Whether a widget of this kind reads a source (the dialog then asks for one). */
export const dashboardKindReadsSource = (kind: DashboardWidgetKind): boolean =>
  kind === "kpi" || kind === "view" || kind === "table";

// The source catalogue ------------------------------------------------------------------

/** A source as the widget dialog lists it. */
export interface DashboardSourceChoice {
  id: string;
  name: string;
  description?: string;
  /** False for sources this user cannot use: listed, not picked. */
  available: boolean;
  /** Why it is unavailable: the host's message, else its reason's text. */
  reason?: string;
}

/** Sources under one heading (a summary's `group`; empty for the others). */
export interface DashboardSourceGroup {
  label: string;
  sources: DashboardSourceChoice[];
}

const COMBINING_MARKS = /[̀-ͯ]/g;
const fold = (value: string): string =>
  value.normalize("NFD").replace(COMBINING_MARKS, "").toLocaleLowerCase();

/** Whether a source matches what is typed: its name, id, description, group or keywords, accents and case aside. */
export function dashboardSourceMatches(
  summary: DashboardSourceSummary,
  query: string,
  locale: string
): boolean {
  const words = fold(query).split(" ").filter(Boolean);
  if (!words.length) {
    return true;
  }
  const haystack = fold(
    [
      summary.id,
      dashboardText(summary.name, locale),
      dashboardText(summary.description, locale),
      dashboardText(summary.group, locale),
      ...(summary.keywords ?? []),
    ].join(" ")
  );
  return words.every((word) => haystack.includes(word));
}

/**
 * The catalogue as the widget dialog lists it: the sources matching `query`,
 * under their group (in the order groups first appear), unavailable ones
 * with the reason they cannot be picked.
 */
export function dashboardSourceChoices(
  summaries: readonly DashboardSourceSummary[],
  options: { query?: string; locale: string; translate?: DashboardTranslate }
): DashboardSourceGroup[] {
  const { locale, translate } = options;
  const groups = new Map<string, DashboardSourceChoice[]>();
  for (const summary of summaries) {
    if (!dashboardSourceMatches(summary, options.query ?? "", locale)) {
      continue;
    }
    const group = dashboardText(summary.group, locale);
    const description = dashboardText(summary.description, locale);
    const available = summary.available !== false;
    const choice: DashboardSourceChoice = {
      id: summary.id,
      name: dashboardText(summary.name, locale) || summary.id,
      ...(description ? { description } : {}),
      available,
      ...(available
        ? {}
        : {
            reason: dashboardUnavailableText(
              summary.unavailableReason,
              summary.unavailableMessage,
              locale,
              translate
            ),
          }),
    };
    groups.set(group, [...(groups.get(group) ?? []), choice]);
  }
  return [...groups].map(([label, sources]) => ({ label, sources }));
}

// The view editor -------------------------------------------------------------------------

/**
 * One session of the view editor: the settings the table starts from and
 * what it reported since (`onViewConfigChange` / `view-config-change`).
 */
export interface DashboardViewEdit {
  /** The widget's view before editing: its inline settings, its saved view's, or `{}`. */
  initial: DashboardInlineView;
  /** The table's first report: the view as the table started. */
  baseline?: ViewConfig;
  /** The table's last report. */
  latest?: ViewConfig;
}

/**
 * The settings a widget's view editor starts from: its inline view, else its
 * saved view's settings (sanitized), else the source's default view (`{}`).
 */
export function dashboardViewEditStart(
  widget: Pick<DashboardWidget, "view" | "viewId">,
  view?: Pick<DashboardView, "id" | "config">
): DashboardViewEdit {
  if (widget.view) {
    return { initial: { ...widget.view } };
  }
  const saved = widget.viewId && view?.id === widget.viewId ? view : undefined;
  return { initial: saved ? canonicalViewConfig(saved.config) : {} };
}

/** The session with the table's report recorded: the first is the baseline. */
export const recordDashboardViewReport = (
  edit: DashboardViewEdit,
  config: ViewConfig
): DashboardViewEdit => ({
  ...edit,
  baseline: edit.baseline ?? config,
  latest: config,
});

const viewJson = (config: unknown) =>
  JSON.stringify(canonicalViewConfig(config));

/** Whether the admin changed the view since the table started (closing then asks first). */
export const dashboardViewEdited = (edit: DashboardViewEdit): boolean =>
  Boolean(edit.baseline && edit.latest) &&
  viewJson(edit.baseline) !== viewJson(edit.latest);

/**
 * What "Apply" stores in `widget.view`: the table's last report, sanitized.
 * The page size is left out unless the admin changed it (a fit widget sizes
 * its records to its card), or the view already had one. Undefined before
 * the table reported.
 */
export function dashboardViewToApply(
  edit: DashboardViewEdit
): DashboardInlineView | undefined {
  if (!edit.latest) {
    return;
  }
  const { pageSize, ...config } = canonicalViewConfig(edit.latest);
  const changed =
    pageSize !== undefined && pageSize !== edit.baseline?.pageSize;
  const kept = changed ? pageSize : edit.initial.pageSize;
  return kept === undefined ? config : { ...config, pageSize: kept };
}

/**
 * Actions that change records or send them somewhere: the view editor's
 * table leaves them out (a manual order is stored per view by `reorder`).
 */
const WRITE_ACTIONS: ReadonlySet<string> = new Set([
  "create",
  "update",
  "delete",
  "duplicate",
  "bulkDelete",
  "bulkCopy",
  "bulkUpdate",
  "import",
  "reorder",
  "destinations",
  "formLinks",
]);
/** The file tree's writes (`actions.tree`); its reads stay. */
const TREE_WRITES: ReadonlySet<string> = new Set(["move", "createFolder"]);
/** The file tree's upload hook (`table.filetree.onDropFiles`). */
const DROP_HOOKS: ReadonlySet<string> = new Set(["onDropFiles"]);

const withoutKeys = (
  value: object,
  keys: ReadonlySet<string>
): Record<string, unknown> =>
  Object.fromEntries(Object.entries(value).filter(([key]) => !keys.has(key)));

/**
 * The source's actions as the view editor's table gets them: reading only
 * (`list`, `aggregate`, the file tree's `path`, planning's reads, which
 * `allowEdit: false` keeps read-only…), so editing a view never changes
 * records.
 */
export function dashboardViewEditorActions<T extends object>(actions: T): T {
  const kept = withoutKeys(actions, WRITE_ACTIONS);
  const { tree } = kept;
  return (
    typeof tree === "object" && tree !== null
      ? { ...kept, tree: withoutKeys(tree, TREE_WRITES) }
      : kept
  ) as T;
}

/**
 * The source's config as the view editor's table gets it: its toolbar
 * (search, filters, sort, columns, display and every mode's settings) without
 * URL sync, saved views, selection or record changes.
 */
export function dashboardViewEditorConfig<T extends { table?: object }>(
  config: T
): T {
  // Files dropped from the desktop would upload through the host's hook.
  const filetree = (config.table as { filetree?: unknown } | undefined)
    ?.filetree;
  const tree =
    typeof filetree === "object" && filetree !== null
      ? { filetree: withoutKeys(filetree, DROP_HOOKS) }
      : {};
  return {
    ...config,
    table: {
      ...config.table,
      ...tree,
      syncUrl: false,
      enableViews: false,
      allowViewSave: false,
      enableRowSelection: false,
      showToolbar: true,
      showToolbarHeader: false,
      allowCreate: false,
      allowEdit: false,
      allowInlineEdit: false,
      allowDelete: false,
      allowDuplicate: false,
      allowBulkEdit: false,
      allowBulkDelete: false,
    },
  };
}

/**
 * The widget with inline settings `view` instead of a saved view. A view
 * widget without a title of its own keeps the saved view's name as its
 * title (`name`), so it reads the same.
 */
export function setDashboardWidgetView(
  dashboard: Dashboard,
  widgetId: string,
  view: DashboardInlineView,
  name?: string
): Dashboard {
  return {
    ...dashboard,
    widgets: dashboard.widgets.map((widget) => {
      if (widget.id !== widgetId) {
        return widget;
      }
      const { viewId: _viewId, ...rest } = widget;
      const keepsName =
        widget.type === "view" &&
        widget.title === undefined &&
        Boolean(widget.viewId && name);
      return {
        ...rest,
        ...(keepsName ? { title: name } : {}),
        view,
      };
    }),
  };
}

/**
 * "Use a copy of this view": a widget's saved view becomes inline settings (a
 * sanitized copy of its `config`), so the screen no longer follows changes
 * to the saved view. Unchanged when the widget does not name that view.
 */
export function copyDashboardWidgetView(
  dashboard: Dashboard,
  widgetId: string,
  view: Pick<DashboardView, "id" | "name" | "config">
): Dashboard {
  const widget = dashboard.widgets.find((item) => item.id === widgetId);
  if (!widget || widget.view || widget.viewId !== view.id) {
    return dashboard;
  }
  return setDashboardWidgetView(
    dashboard,
    widgetId,
    canonicalViewConfig(view.config),
    view.name
  );
}

// Block props ---------------------------------------------------------------------------

/** Props typed as JSON in the widget dialog, as the editor reads them. */
export interface DashboardBlockPropsDraft {
  /** False when the text is not JSON: the props are refused. */
  json: boolean;
  /** The props to apply, when nothing refused them. */
  props?: DashboardJsonObject;
  /** Why they are refused (errors) or what to know (warnings), with paths inside the props. */
  issues: DashboardIssue[];
  ok: boolean;
}

/** The props as the dialog's JSON text shows them. */
export const dashboardBlockPropsText = (
  props: DashboardJsonObject | undefined
): string => JSON.stringify(props ?? {}, null, 2);

/**
 * Props typed as JSON: parsed, then checked as `validateDashboard` does (a
 * JSON object, copied safely, then the block's `validateProps`). Invalid
 * JSON and errors refuse them.
 */
export function parseDashboardBlockProps(
  text: string,
  block: string,
  options: { blocks?: DashboardBlocks; limits?: Partial<DashboardLimits> } = {}
): DashboardBlockPropsDraft {
  let value: unknown;
  try {
    value = text.trim() ? JSON.parse(text) : {};
  } catch {
    return { json: false, issues: [], ok: false };
  }
  const checked = checkDashboardBlockProps(block, value, options);
  return {
    json: true,
    issues: checked.issues,
    ok: checked.ok,
    ...(checked.ok ? { props: checked.props } : {}),
  };
}

// Validation before saving ------------------------------------------------------------------

const WIDGET_PATH = /^widgets\[(\d+)\]/;
const SECTION_PATH = /^sections\[(\d+)\]/;
const FILTER_PATH = /^filters\[(\d+)\]/;

/** What a validation issue is about, by id: a widget, a section or a filter of the document checked. */
export interface DashboardIssueTarget {
  widgetId?: string;
  sectionId?: string;
  filterId?: string;
}

/** The widget, section or filter an issue's path (`widgets[2].props.unit`) points into. */
export function dashboardIssueTarget(
  dashboard: Pick<Dashboard, "widgets" | "sections" | "filters">,
  issue: Pick<DashboardIssue, "path">
): DashboardIssueTarget {
  const path = issue.path ?? "";
  const at = (pattern: RegExp) => {
    const match = pattern.exec(path);
    return match ? Number(match[1]) : undefined;
  };
  const widget = at(WIDGET_PATH);
  if (widget !== undefined) {
    const id = dashboard.widgets[widget]?.id;
    return id ? { widgetId: id } : {};
  }
  const section = at(SECTION_PATH);
  if (section !== undefined) {
    const id = dashboard.sections[section]?.id;
    return id ? { sectionId: id } : {};
  }
  const filter = at(FILTER_PATH);
  const id = filter === undefined ? undefined : dashboard.filters[filter]?.id;
  return id ? { filterId: id } : {};
}

/** Issues that stop a save: the errors (`validateDashboard`'s `ok` is false with any). */
export const dashboardSaveErrors = (
  issues: readonly DashboardIssue[]
): DashboardIssue[] => issues.filter((issue) => issue.severity === "error");

import { defineComponent, h, markRaw } from "vue";
import DashboardFacetBlock from "./DashboardFacetBlock.vue";
import { type FacetBlockOptions, facetBlockSchema } from "./dashboard-facets";
import type { DashboardBlock } from "./dashboard-types";

/**
 * The "Facet list" block: a column's values with their numbers of records;
 * a click sets a screen filter (`filterId`, a select filter on the column),
 * which drives every widget it targets, such as a full-page table. Counts
 * come from `actions.aggregate` (grouped by the column), else from the rows
 * `actions.list` returns, under the screen's other filters.
 */
export function createFacetBlock(options: FacetBlockOptions): DashboardBlock {
  const component = markRaw(
    defineComponent({
      name: "FacetListBlock",
      inheritAttrs: false,
      setup:
        (_props, { attrs }) =>
        () =>
          h(DashboardFacetBlock as never, { ...attrs, options }),
    })
  );
  return { ...facetBlockSchema(options), component };
}

/**
 * The "Facet list" block, shared by the React and Vue editions (synced to
 * Vue): a column's values with their numbers of records; a click sets a
 * screen filter through the block's `setFilter`, so a tag or category
 * navigation drives a full-page table (and every widget the filter targets).
 * Pure: the block's schema and props, its counts' request, its values.
 */
import {
  type FacetColumn,
  type FacetColumnInput,
  type FacetCounts,
  type FacetEntry,
  facetEntries,
  facetKind,
  loadFacetCounts,
} from "../facets-model";
import type { ScopedRowsRequest } from "../scoped-rows";
import {
  type DashboardTranslate,
  dashboardLabel,
  withDashboardFilters,
} from "./dashboard-model";
import {
  type DashboardBlockSchema,
  type DashboardJsonObject,
  type DashboardText,
  dashboardSelectValues,
} from "./dashboard-schema";

type UnknownRecord = Record<string, unknown>;

/** How the block lays its values out: a list (a side navigation) or chips in a row. */
export type FacetBlockLayout = "chips" | "list";

/** The block's props (JSON, in the document). */
export interface FacetBlockProps {
  /** The screen filter the block sets; the factory's `filterId` by default. */
  filterId?: string;
  layout?: FacetBlockLayout;
  /** Show each value's number of records (default true). */
  showCounts?: boolean;
}

/** The source's actions the block counts with (its `aggregate`, else its `list`). */
export interface FacetBlockActions {
  aggregate?: (params: never) => unknown;
  list?: (params: never) => unknown;
}

/** What `createFacetBlock` takes, in both editions. */
export interface FacetBlockOptions {
  /** The screen filter the block sets: a select filter targeting the column. */
  filterId: string;
  /** The source whose records the block counts. */
  tableId: string;
  /** The column listed: its values' labels (`options`) and type. */
  column: FacetColumnInput;
  /** The source's actions, for the counts; without them, the options show without counts. */
  actions?: FacetBlockActions;
  /** The block's name in the widget dialog ("Facet list"). */
  label?: DashboardText;
  description?: DashboardText;
  group?: DashboardText;
  /** Where the block goes (default any section). */
  placement?: DashboardBlockSchema["placement"];
  defaultSize?: { w: number; h: number };
  /** The layout of new widgets (default "list"). */
  layout?: FacetBlockLayout;
}

const LAYOUTS: readonly FacetBlockLayout[] = ["chips", "list"];
const FILTER_ID = /^[\p{L}\p{N}][\p{L}\p{N}_-]{0,63}$/u;

/** The facet the block lists: the column's values (select, list or yes/no). */
export function facetBlockColumn(
  column: FacetColumnInput,
  locale = "en"
): FacetColumn {
  const kind = facetKind(column) ?? "select";
  const options = Array.isArray(column.options)
    ? column.options.flatMap((item) => {
        const option = (item ?? {}) as UnknownRecord;
        return "value" in option
          ? [
              {
                value: String(option.value),
                label: String(option.label ?? option.value ?? ""),
              },
            ]
          : [];
      })
    : [];
  const booleans =
    kind === "boolean"
      ? [
          { value: "true", label: locale.startsWith("fr") ? "Oui" : "Yes" },
          { value: "false", label: locale.startsWith("fr") ? "Non" : "No" },
        ]
      : [];
  return {
    id: column.id,
    label: column.header ?? column.id,
    kind: kind === "folder" ? "select" : kind,
    type: kind === "multiSelect" ? "multiSelect" : "select",
    operator: kind === "multiSelect" ? "contains" : "isAnyOf",
    options: kind === "boolean" ? booleans : options,
    limit: Number.POSITIVE_INFINITY,
    sort: options.length || kind === "boolean" ? "options" : "count",
    showEmpty: false,
  };
}

/** The block's props with its defaults. */
export function facetBlockProps(
  props: unknown,
  options: Pick<FacetBlockOptions, "filterId" | "layout">
): { filterId: string; layout: FacetBlockLayout; showCounts: boolean } {
  const source = (props ?? {}) as UnknownRecord;
  const filterId =
    typeof source.filterId === "string" && FILTER_ID.test(source.filterId)
      ? source.filterId
      : options.filterId;
  const layout =
    LAYOUTS.find((item) => item === source.layout) ?? options.layout ?? "list";
  return { filterId, layout, showCounts: source.showCounts !== false };
}

/** The problems of the block's props: `filterId` an id, `layout` list or chips, `showCounts` yes or no. */
export function facetBlockProblems(
  props: DashboardJsonObject
): { message: string; path: string }[] | undefined {
  const problems: { message: string; path: string }[] = [];
  if (
    props.filterId !== undefined &&
    !(typeof props.filterId === "string" && FILTER_ID.test(props.filterId))
  ) {
    problems.push({ message: "filterId is a filter's id.", path: "filterId" });
  }
  if (
    props.layout !== undefined &&
    !LAYOUTS.includes(props.layout as FacetBlockLayout)
  ) {
    problems.push({ message: "layout is list or chips.", path: "layout" });
  }
  if (props.showCounts !== undefined && typeof props.showCounts !== "boolean") {
    problems.push({
      message: "showCounts is true or false.",
      path: "showCounts",
    });
  }
  return problems.length ? problems : undefined;
}

/** The block's schema: what `validateDashboard` and the widget dialog read. */
export function facetBlockSchema(
  options: FacetBlockOptions
): DashboardBlockSchema {
  return {
    label: options.label ?? {
      en: dashboardLabel("facetBlock", "en"),
      fr: dashboardLabel("facetBlock", "fr"),
    },
    description: options.description ?? {
      en: dashboardLabel("facetBlockDescription", "en"),
      fr: dashboardLabel("facetBlockDescription", "fr"),
    },
    ...(options.group ? { group: options.group } : {}),
    placement: options.placement ?? "any",
    defaultSize: options.defaultSize ?? { w: 1, h: 3 },
    defaultProps: { layout: options.layout ?? "list" },
    validateProps: facetBlockProblems,
    propsSchema: {
      type: "object",
      properties: {
        filterId: { type: "string" },
        layout: { enum: [...LAYOUTS] },
        showCounts: { type: "boolean" },
      },
    },
  };
}

/** The values a click leaves in the filter: the value joins or leaves them. */
export function toggleFacetBlockValue(
  current: unknown,
  value: string
): string[] {
  const values = dashboardSelectValues(current);
  return values.includes(value)
    ? values.filter((item) => item !== value)
    : [...values, value];
}

/**
 * The block's counts: the source's `aggregate` grouped by the column (else
 * the rows `list` returns, 2,000 at most), under the screen's other filters
 * (`rules`, joined to every request as the widgets' are).
 */
export async function loadFacetBlockCounts(input: {
  actions?: FacetBlockActions;
  column: FacetColumn;
  rules: readonly UnknownRecord[];
  locale: string;
  signal?: AbortSignal;
}): Promise<FacetCounts | undefined> {
  if (!(input.actions?.aggregate || input.actions?.list)) {
    return;
  }
  const actions = withDashboardFilters(input.actions, input.rules) as {
    aggregate?: (params: UnknownRecord) => unknown;
    list?: ScopedRowsRequest["list"];
  };
  const counts = await loadFacetCounts({
    facets: [input.column],
    params: { search: "", filters: {}, advancedFilters: [] },
    aggregate: actions.aggregate,
    list: actions.list,
    locale: input.locale,
    signal: input.signal,
  });
  return counts[input.column.id];
}

/** The values the block lists: its options and the counted ones, selected ones first kept. */
export const facetBlockEntries = (
  column: FacetColumn,
  input: { counts?: FacetCounts; selected: unknown; locale: string }
): FacetEntry[] =>
  facetEntries(column, {
    counts: input.counts,
    selection: { values: dashboardSelectValues(input.selected), empty: false },
    locale: input.locale,
  });

/** A label of the block, overridable with `dashboard.<key>`. */
export const facetBlockLabel = (
  key: "facetAll" | "facetClear" | "facetEmpty" | "facetError" | "facetLoading",
  locale: string,
  translate?: DashboardTranslate
): string => dashboardLabel(key, locale, translate);

/**
 * Fit widgets (`settings.overflow: "fit"`, the default) show the records that
 * fit their height and nothing scrolls. Shared by the React and Vue editions:
 * both mark each record of a table, list, gallery, board and feed with
 * `data-row-id`, board lanes with `data-kanban-lane` and the board with
 * `data-kanban-board`. Hidden records carry `data-dashboard-overflow`, which
 * `dashboard-grid.css` hides.
 */

const RECORD = "[data-row-id]";
const BOARD = "[data-kanban-board]";
const LANE = "[data-kanban-lane]";
export const DASHBOARD_OVERFLOW_ATTRIBUTE = "data-dashboard-overflow";
const HIDDEN = `[${DASHBOARD_OVERFLOW_ATTRIBUTE}]`;
/** Sub-pixel rounding is not overflow. */
const TOLERANCE = 1;
/**
 * Space a view may keep below its last record (paddings and borders of its
 * list, board or feed). Overflow left once every record ends this far above
 * the bottom is not the records' doing: the widget clips it.
 */
const TRAILING_SPACE = 40;
/** Columns a table keeps, however narrow the widget. */
const MIN_COLUMNS = 2;

export interface DashboardFitResult {
  /** Records shown. */
  shown: number;
  /** Records loaded but hidden. */
  hidden: number;
}

const hide = (element: Element) =>
  element.setAttribute(DASHBOARD_OVERFLOW_ATTRIBUTE, "");
const isShown = (element: Element) =>
  !element.closest(HIDDEN) && element.getClientRects().length > 0;
/** Records of the container, the outer one only when a record holds another (a feed post in its item). */
const recordsOf = (container: HTMLElement) =>
  [...container.querySelectorAll(RECORD)].filter(
    (record) => !record.parentElement?.closest(RECORD)
  );

/** Lanes that do not fit the width are hidden from the right; one always stays. */
function fitLanes(container: HTMLElement) {
  for (const board of container.querySelectorAll<HTMLElement>(BOARD)) {
    const lanes = [...board.querySelectorAll(LANE)];
    let shown = lanes.length;
    while (shown > 1 && board.scrollWidth > board.clientWidth + TOLERANCE) {
      shown -= 1;
      const lane = lanes[shown];
      if (lane) {
        hide(lane);
      }
    }
  }
}

/** Table columns that do not fit the width are hidden from the right. */
function fitColumns(container: HTMLElement) {
  for (const table of container.querySelectorAll("table")) {
    const frame = table.parentElement ?? container;
    const rows = [...table.rows];
    const width = Math.max(0, ...rows.map((row) => row.cells.length));
    let shown = width;
    while (
      shown > MIN_COLUMNS &&
      table.getBoundingClientRect().width > frame.clientWidth + TOLERANCE
    ) {
      shown -= 1;
      for (const row of rows) {
        const cell = row.cells.length === width ? row.cells[shown] : undefined;
        if (cell) {
          hide(cell);
        }
      }
    }
  }
}

/** The shown record reaching lowest (the last one in reading order on ties). */
function lowestRecord(records: readonly Element[]) {
  let lowest: { record: Element; bottom: number } | undefined;
  for (const record of records) {
    const bottom = record.getBoundingClientRect().bottom;
    if (!lowest || bottom >= lowest.bottom) {
      lowest = { record, bottom };
    }
  }
  return lowest;
}

/**
 * Records hide from the lowest up while the content overflows, which also
 * accounts for the paddings and borders below them. Records starting below
 * the visible area go first, at once. The first line always stays (the
 * first record, a gallery's first row of cards, each lane's first card).
 */
function fitRecords(container: HTMLElement) {
  const overflows = () =>
    container.scrollHeight > container.clientHeight + TOLERANCE;
  if (!overflows()) {
    return;
  }
  const records = recordsOf(container).filter(isShown);
  const firstTop = records.at(0)?.getBoundingClientRect().top ?? 0;
  const kept = new Set(
    records.filter(
      (record) =>
        Math.abs(record.getBoundingClientRect().top - firstTop) <= TOLERANCE
    )
  );
  const box = container.getBoundingClientRect();
  const bottom = box.top + container.clientTop + container.clientHeight;
  let shown = records.filter((record) => !kept.has(record));
  for (const record of shown) {
    if (record.getBoundingClientRect().top >= bottom) {
      hide(record);
    }
  }
  shown = shown.filter(isShown);
  while (shown.length && overflows()) {
    const lowest = lowestRecord(shown);
    if (!lowest || lowest.bottom <= bottom - TRAILING_SPACE) {
      return;
    }
    hide(lowest.record);
    shown = shown.filter((record) => record !== lowest.record);
  }
}

/**
 * Hides the records, lanes and columns that do not fit in `container` (an
 * element that clips, with a definite height) and counts the records left.
 */
export function fitDashboardRecords(
  container: HTMLElement
): DashboardFitResult {
  for (const element of container.querySelectorAll(HIDDEN)) {
    element.removeAttribute(DASHBOARD_OVERFLOW_ATTRIBUTE);
  }
  fitLanes(container);
  fitColumns(container);
  fitRecords(container);
  const records = recordsOf(container);
  const shown = records.filter(isShown).length;
  return { shown, hidden: records.length - shown };
}

/**
 * Fits `container` now and again when it resizes, its content changes,
 * images load or fonts arrive; `onFit` hears each new result.
 */
export function observeDashboardFit(
  container: HTMLElement,
  onFit: (result: DashboardFitResult) => void
): () => void {
  const view = container.ownerDocument.defaultView;
  let disposed = false;
  let last = "";
  const refit = () => {
    if (disposed || !container.isConnected) {
      return;
    }
    const result = fitDashboardRecords(container);
    const key = `${result.shown}:${result.hidden}`;
    if (key !== last) {
      last = key;
      onFit(result);
    }
  };
  // Both run before paint, so records never flash in before hiding.
  const resize =
    typeof view?.ResizeObserver === "function"
      ? new view.ResizeObserver(refit)
      : undefined;
  resize?.observe(container);
  const mutation =
    typeof view?.MutationObserver === "function"
      ? new view.MutationObserver(refit)
      : undefined;
  mutation?.observe(container, {
    childList: true,
    subtree: true,
    characterData: true,
  });
  container.addEventListener("load", refit, true);
  container.ownerDocument.fonts?.ready.then(refit).catch(() => undefined);
  refit();
  return () => {
    disposed = true;
    resize?.disconnect();
    mutation?.disconnect();
    container.removeEventListener("load", refit, true);
  };
}

/**
 * The desktop grid, driven by gridstack.js in both editions. Loaded on demand
 * (`import("./dashboard-grid-engine")`) with gridstack's styles, so neither
 * the table nor phones download it. The framework renders the items
 * (`.grid-stack-item[gs-id]`); this controller hands them to gridstack and
 * reports the positions users drag and resize to.
 */
import "gridstack/dist/gridstack.min.css";
import { type GridItemHTMLElement, GridStack } from "gridstack";
import {
  DASHBOARD_COLUMNS,
  DASHBOARD_MARGIN,
  DASHBOARD_ROW_HEIGHT,
  type DashboardLayoutItem,
} from "./dashboard-layout";

export interface DashboardGridController {
  /** Hands new items to gridstack, drops removed ones and applies `layout`. */
  sync: (layout: readonly DashboardLayoutItem[], editing: boolean) => void;
  destroy: () => void;
}

const itemElements = (element: HTMLElement): GridItemHTMLElement[] =>
  [...element.children].filter(
    (child): child is GridItemHTMLElement =>
      child instanceof HTMLElement &&
      child.classList.contains("grid-stack-item")
  );

const place = (item: DashboardLayoutItem) => ({
  x: item.x,
  y: item.y,
  w: item.w,
  h: item.h,
});

const differs = (
  element: GridItemHTMLElement,
  item: DashboardLayoutItem
): boolean => {
  const node = element.gridstackNode;
  return (
    !node ||
    node.x !== item.x ||
    node.y !== item.y ||
    node.w !== item.w ||
    node.h !== item.h
  );
};

/** Starts gridstack on the grid element; `onChange` receives every widget's place after a drag or resize. */
export function mountDashboardGrid(
  element: HTMLElement,
  options: {
    editing: boolean;
    onChange: (layout: DashboardLayoutItem[]) => void;
  }
): DashboardGridController {
  const grid = GridStack.init(
    {
      column: DASHBOARD_COLUMNS,
      cellHeight: DASHBOARD_ROW_HEIGHT,
      margin: DASHBOARD_MARGIN,
      handle: "[data-dashboard-drag-handle]",
      animate: false,
      disableDrag: !options.editing,
      disableResize: !options.editing,
      resizable: { handles: "se" },
    },
    element
  );
  if (!grid) {
    throw new Error("gridstack could not start on the dashboard grid.");
  }
  let syncing = false;
  const report = () => {
    if (syncing) {
      return;
    }
    const layout: DashboardLayoutItem[] = [];
    for (const node of grid.engine.nodes) {
      if (node.id) {
        layout.push({
          widgetId: String(node.id),
          x: node.x ?? 0,
          y: node.y ?? 0,
          w: node.w ?? 1,
          h: node.h ?? 1,
        });
      }
    }
    options.onChange(layout);
  };
  grid.on("change", report);

  const sync = (layout: readonly DashboardLayoutItem[], editing: boolean) => {
    syncing = true;
    grid.batchUpdate();
    try {
      for (const node of [...grid.engine.nodes]) {
        if (node.el && node.el.parentElement !== element) {
          grid.removeWidget(node.el, false, false);
        }
      }
      for (const child of itemElements(element)) {
        const id = child.getAttribute("gs-id");
        const item = layout.find((entry) => entry.widgetId === id);
        if (item && !child.gridstackNode) {
          grid.makeWidget(child, { id: item.widgetId, ...place(item) });
        } else if (item && differs(child, item)) {
          grid.update(child, place(item));
        }
      }
    } finally {
      grid.batchUpdate(false);
      syncing = false;
    }
    grid.enableMove(editing);
    grid.enableResize(editing);
  };

  return {
    sync,
    destroy: () => {
      grid.offAll();
      grid.destroy(false);
    },
  };
}

/*
 * Dashboard grid, shared by the React and Vue editions. gridstack.js places
 * the widgets on desktop once loaded; until then (and when it cannot load)
 * these rules put them where the layout says. Phones stack them.
 */
.yayaw-dashboard-grid {
  --dashboard-columns: 4;
  position: relative;
  min-height: calc(var(--dashboard-rows, 1) * var(--dashboard-row-height));
}
.yayaw-dashboard-grid:not([data-grid-ready]) > .grid-stack-item {
  position: absolute;
  left: calc(var(--dashboard-x) * 100% / var(--dashboard-columns));
  top: calc(var(--dashboard-y) * var(--dashboard-row-height));
  width: calc(var(--dashboard-w) * 100% / var(--dashboard-columns));
  height: calc(var(--dashboard-h) * var(--dashboard-row-height));
}
.yayaw-dashboard-grid:not([data-grid-ready])
  > .grid-stack-item
  > .grid-stack-item-content {
  position: absolute;
  inset: var(--dashboard-margin);
}
.yayaw-dashboard-grid > .grid-stack-item > .grid-stack-item-content {
  overflow: visible;
}
.yayaw-dashboard-grid .grid-stack-placeholder > .placeholder-content {
  border: 2px dashed var(--ring, oklch(0.708 0 0));
  border-radius: calc(var(--radius, 0.625rem) + 2px);
  background: color-mix(
    in oklab,
    var(--muted, oklch(0.97 0 0)) 70%,
    transparent
  );
}
.yayaw-dashboard-grid > .grid-stack-item > .ui-resizable-se {
  right: calc(var(--dashboard-margin) + 2px);
  bottom: calc(var(--dashboard-margin) + 2px);
  border-radius: 4px;
  background-color: var(--background, oklch(1 0 0));
  opacity: 0.9;
}
.yayaw-dashboard-grid [data-dashboard-drag-handle] {
  cursor: grab;
  touch-action: none;
}
/* Phones: one column, each widget as tall as its rows by default. */
.yayaw-dashboard-stack {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: calc(var(--dashboard-margin) * 2);
}
.yayaw-dashboard-stack > [data-dashboard-item] {
  display: flex;
  min-width: 0;
  height: calc(
    var(--dashboard-h) *
    var(--dashboard-row-height) -
    var(--dashboard-margin) *
    2
  );
}
.yayaw-dashboard-stack > [data-dashboard-item] > * {
  flex: 1;
  min-width: 0;
}
/*
 * Rows are sized for a quarter of a desktop grid, not for a phone: figures,
 * notes and host blocks take the height of their content, charts one
 * proportional to the phone's width. Record widgets keep their rows, which
 * set how many they show.
 */
.yayaw-dashboard-stack
> [data-dashboard-item]:has(
  [data-widget-type="kpi"],
  [data-widget-type="note"],
  [data-widget-type="block"],
  [data-widget-mode="chart"]
) {
  height: auto;
}
.yayaw-dashboard-stack [data-widget-type="kpi"] > [data-widget-body],
.yayaw-dashboard-stack [data-widget-type="note"] > [data-widget-body],
.yayaw-dashboard-stack [data-widget-type="block"] > [data-widget-body] {
  flex: none;
  container-type: inline-size;
}
.yayaw-dashboard-stack
  [data-dashboard-widget]:has([data-widget-mode="chart"])
  > [data-widget-body] {
  flex: none;
  height: auto;
  min-height: 11rem;
  max-height: 20rem;
  aspect-ratio: 16 / 10;
}
/* Widgets line up with the toolbar despite their margins. */
[data-dashboard-layout="grid"] {
  margin-inline: calc(var(--dashboard-margin) * -1);
}

/*
 * Widget bodies are size containers: charts fill them (`100cqh`). They clip,
 * unless the widget asks to scroll (`settings.overflow: "scroll"`).
 */
[data-dashboard-widget] > [data-widget-body] {
  container-type: size;
  overflow: hidden;
}
[data-dashboard-widget] > [data-widget-body][data-overflow="scroll"] {
  overflow: auto;
}

/*
 * Flow sections: widgets one under the other, at full width and the height
 * of their content. Bodies grow with it (no size container, nothing clipped),
 * so records keep the view's pagination; charts take a 16:10 body, as on
 * phones, since they fill their container.
 */
.yayaw-dashboard-flow {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: calc(var(--dashboard-margin, 6px) * 2);
}
.yayaw-dashboard-flow > [data-dashboard-item] {
  display: flex;
  min-width: 0;
}
.yayaw-dashboard-flow > [data-dashboard-item] > * {
  flex: 1;
  min-width: 0;
}
.yayaw-dashboard-flow [data-dashboard-widget] > [data-widget-body] {
  container-type: inline-size;
  overflow: visible;
}
.yayaw-dashboard-flow
  [data-dashboard-widget]:has([data-widget-mode="chart"])
  > [data-widget-body] {
  container-type: size;
  height: auto;
  min-height: 11rem;
  max-height: 24rem;
  aspect-ratio: 16 / 10;
}

/* Fit: the records that do not fit are hidden (dashboard-fit.ts). */
[data-dashboard-fit] {
  display: flex;
  flex: 1 1 0%;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}
[data-dashboard-fit] [data-dashboard-overflow] {
  display: none !important;
}
[data-dashboard-fit] [data-feed-footer] {
  display: none !important;
}
/* No space kept below the records for pagination or bulk actions. */
[data-dashboard-fit] [data-yayaw-table-selection-scope] > * {
  margin-block: 0;
}
/* Boards share the widget's width; lanes that do not fit are hidden. */
[data-dashboard-fit] [data-kanban-board],
[data-dashboard-fit] [data-kanban-board] > * {
  width: auto;
  min-width: 0;
  min-height: 0;
  grid-auto-columns: minmax(9rem, 1fr);
}
[data-dashboard-fit] [data-kanban-board] {
  overflow: hidden;
}
[data-dashboard-fit] [data-kanban-lane] {
  width: auto;
  min-width: 0;
  min-height: 0;
}

/* "+3 more · View all" under a fit widget's records. */
[data-widget-more] {
  display: flex;
  flex: none;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.25rem 0.375rem;
  padding-top: 0.375rem;
